fix.code:
# Cách làm đúng, tính từ trạng thái trước sự cố (count với 3 queue)
variable "order_queues" {
  type    = set(string)
  default = ["orders-created", "orders-paid", "orders-shipped"]   # PR 1
}

resource "aws_sqs_queue" "events" {
  for_each                  = var.order_queues
  name                      = each.key
  message_retention_seconds = 345600

  lifecycle {
    prevent_destroy = true      # muốn xoá thật thì bỏ dòng này trong một PR riêng
  }
}

# Chuyển địa chỉ cũ sang khoá mới, không xoá tạo lại gì cả
moved {
  from = aws_sqs_queue.events[1]
  to   = aws_sqs_queue.events["orders-paid"]
}
moved {
  from = aws_sqs_queue.events[0]
  to   = aws_sqs_queue.events["orders-created"]
}
moved {
  from = aws_sqs_queue.events[2]
  to   = aws_sqs_queue.events["orders-shipped"]
}
# Làm hai pull request:
#  PR 1: đổi sang for_each + moved, vẫn giữ "orders-paid" trong danh sách -> plan: 0 to add, 0 to change, 0 to destroy
#  PR 2: bỏ "orders-paid" và tạm bỏ prevent_destroy -> plan: 0 to add, 0 to change, 1 to destroy

